WITH CustomerSummary AS (SELECT customer_id, MAX(end_date) AS latest_end_date, COUNT(CASE WHEN plan = 'enterprise' THEN 1 END) AS enterprise_count FROM subscriptions WHERE plan NOT IN ('premium', 'enterprise', 'basic') GROUP BY customer_id) SELECT c.id, c.name, C.latest_end_date, C.enterprise_count FROM customers c LEFT JOIN CustomerSummary C ON c.id = C.customer_id ORDER BY c.name;
